import SwiftUI

struct ContextualTriggersView: View { @ObservedObject var viewModel: ContextualTriggersViewModel
    var body: some View { AppCard { VStack(alignment:.leading, spacing:MindMorySpacing.md){ Text("Contextual Triggers").font(MindMoryTypography.headingMedium); Toggle("Location-based reminders", isOn:$viewModel.settings.locationBasedReminders); Toggle("Public holiday reminders", isOn:$viewModel.settings.publicHolidayReminders); Toggle("Calendar/EventKit reminders", isOn:$viewModel.settings.calendarReminders); Toggle("User pattern / schedule", isOn:$viewModel.settings.userPatternReminders); Toggle("Recent activity", isOn:$viewModel.settings.recentActivityReminders); VStack(alignment:.leading){ Text("Notification wording preference").font(MindMoryTypography.caption); Text(viewModel.settings.notificationWordingPreference).font(MindMoryTypography.bodyMedium).foregroundStyle(MindMoryColors.primaryGreen) }; Button("Save trigger preferences", action:viewModel.save).font(MindMoryTypography.bodyMedium).foregroundStyle(MindMoryColors.primaryGreen) }.toggleStyle(SwitchToggleStyle(tint: MindMoryColors.primaryGreen)) } }
}
